27	/* Momma Design System - Cores e estilos baseados na identidade visual */
28	
29	@layer base {
30	  :root {
31	    /* Sistema de cores Pantone da empresa - Modo Claro */
32	    /* Cores Pantone convertidas para HSL (regra 70-20-10 aprimorada) */
33	    --pantone-primary: 35 33% 55%;    /* #B49364 - Marrom dourado (20%) */
34	    --pantone-background: 46 63% 95%; /* #F3ECD4 - Bege claro (70%) */
35	    --pantone-accent: 133 17% 33%;    /* #33733F - Verde escuro (10%) */
36	    --pantone-foreground: 60 7% 20%;   /* #3C3B34 - Cinza escuro (texto) */
37	    
38	    /* Sistema de cores baseado na regra 70-20-10 (sem verde oliva) */
39	    --background: 46 63% 95%; /* Bege claro (70%) - #F3ECD4 */
40	    --foreground: 60 7% 20%;  /* Cinza escuro - #3C3B34 */
41	
42	    --card: 46 63% 98%; /* Bege muito claro */
43	    --card-foreground: 60 7% 20%;
44	
45	    --popover: 46 63% 98%;
46	    --popover-foreground: 60 7% 20%;
47	
48	    --primary: 35 33% 55%; /* Marrom dourado (20%) - #B49364 */
49	    --primary-foreground: 46 63% 98%; /* Texto claro sobre marrom */
50	
51	    --secondary: 35 25% 45%; /* Marrom médio (substituto harmonioso) */
52	    --secondary-foreground: 46 63% 98%; /* Texto claro */
53	
54	    --muted: 46 40% 92%; /* Bege suave */
55	    --muted-foreground: 35 20% 40%; /* Marrom escuro suave */
56	
57	    --accent: 133 17% 33%; /* Verde escuro (10%) - #33733F */
58	    --accent-foreground: 46 63% 98%; /* Texto claro sobre verde escuro */
59	
60	    --destructive: 0 75% 60%;
61	    --destructive-foreground: 0 0% 100%;
62	
63	    --success: 133 17% 33%; /* Verde escuro para sucesso */
64	    --success-foreground: 46 63% 98%; /* Texto claro */
65	
66	    --warning: 35 33% 55%; /* Marrom dourado para avisos */
67	    --warning-foreground: 46 63% 98%; /* Texto claro */
68	
69	    --border: 35 25% 80%; /* Borda marrom claro */
70	    --input: 46 30% 90%; /* Input bege */
71	    --ring: 35 33% 55%; /* Ring marrom dourado */
72	
73	    --radius: 0.75rem; /* Border radius aumentado para design moderno */
74	
75	    --sidebar-background: 46 63% 97%; /* Bege claro */
76	    --sidebar-foreground: 60 7% 20%; /* Cinza escuro */
77	    --sidebar-primary: 35 33% 55%; /* Marrom dourado */
78	    --sidebar-primary-foreground: 46 63% 98%; /* Texto claro */
79	    --sidebar-accent: 133 17% 33%; /* Verde escuro */
80	    --sidebar-accent-foreground: 46 63% 98%; /* Texto claro */
81	    --sidebar-border: 35 25% 85%; /* Borda marrom claro */
82	    --sidebar-ring: 35 33% 55%; /* Ring marrom dourado */
83	
84	    /* Tokens de cores da empresa para Tailwind */
85	    --company-verde-escuro: 133 17% 33%;
86	    --company-verde-claro: 133 17% 45%;
87	    --company-bege: 46 63% 95%;
88	    --company-marrom: 35 33% 55%;
89	    --company-cinza-escuro: 60 7% 20%;
90	
91	    /* Tokens Momma utilizados em gradientes e botões especiais */
92	    --momma-primary: var(--primary);
93	    --momma-primary-dark: 35 33% 45%;
94	    --momma-gradient-start: var(--primary);
95	    --momma-gradient-end: var(--accent);
96	
97	    /* ── MIA Chat Custom Properties ── */
98	    /* ── MIA vars — definição canônica em src/features/mia/styles/mia-chat.css.
99	       NÃO redefinir aqui para evitar override do design system da Mia. ── */
100	  }
101	
102	  .dark {
103	    /* Sistema de cores Pantone da empresa - Modo Escuro */
104	    /* Inversão da regra 70-20-10 para modo escuro (sem verde oliva) */
105	    --background: 60 7% 15%; /* Cinza muito escuro (70%) - #262624 */
106	    --foreground: 46 63% 90%; /* Bege claro para texto */
107	
108	    /* Cards - tons escuros com toques quentes */
109	    --card: 35 15% 20%; /* Marrom escuro (20%) */
110	    --card-foreground: 46 63% 90%; /* Texto bege claro */
111	
112	    --popover: 35 15% 18%; /* Marrom um pouco mais escuro */
113	    --popover-foreground: 46 63% 90%;
114	
115	    /* Primário - marrom dourado mais suave no escuro */
116	    --primary: 35 33% 45%; /* Marrom dourado escuro (20%) */
117	    --primary-foreground: 46 63% 98%; /* Texto muito claro */
118	
119	    /* Secundário - marrom médio escuro */
120	    --secondary: 35 25% 35%; /* Marrom médio escuro */
121	    --secondary-foreground: 46 63% 98%; /* Texto muito claro */
122	
123	    /* Tons suaves e muted */
124	    --muted: 35 15% 22%; /* Marrom escuro suave */
125	    --muted-foreground: 46 40% 75%; /* Bege médio */
126	
127	    /* Accent - verde escuro mais vibrante */
128	    --accent: 133 17% 40%; /* Verde escuro intenso (10%) */
129	    --accent-foreground: 46 63% 98%; /* Texto muito claro */
130	
131	    /* Destructive - mantido consistente */
132	    --destructive: 0 70% 42%;
133	    --destructive-foreground: 0 0% 100%;
134	
135	    /* Success - verde escuro */
136	    --success: 133 17% 40%; /* Verde escuro intenso */
137	    --success-foreground: 46 63% 98%; /* Texto muito claro */
138	
139	    /* Warning - marrom dourado */
140	    --warning: 35 33% 45%; /* Marrom dourado escuro */
141	    --warning-foreground: 46 63% 98%; /* Texto muito claro */
142	
143	    /* Bordas - marrom escuro */
144	    --border: 35 15% 25%; /* Borda marrom escuro */
145	    --input: 35 15% 22%; /* Input marrom escuro */
146	    --ring: 35 33% 45%; /* Ring marrom dourado */
147	
148	    /* Sidebar - tons consistentes com modo escuro */
149	    --sidebar-background: 35 15% 18%; /* Marrom muito escuro */
150	    --sidebar-foreground: 46 63% 90%; /* Texto bege */
151	    --sidebar-primary: 35 33% 45%; /* Marrom dourado escuro */
152	    --sidebar-primary-foreground: 46 63% 98%; /* Texto muito claro */
153	    --sidebar-accent: 133 17% 40%; /* Verde escuro intenso */
154	    --sidebar-accent-foreground: 46 63% 98%; /* Texto muito claro */
155	    --sidebar-border: 35 15% 22%; /* Borda marrom */
156	    --sidebar-ring: 35 33% 45%; /* Ring marrom dourado */
157	
158	    /* Tokens de cores da empresa para Tailwind - Modo Escuro */
159	    --company-verde-escuro: 133 17% 40%;
160	    --company-verde-claro: 133 17% 50%;
161	    --company-bege: 46 63% 85%;
162	    --company-marrom: 35 33% 45%;
163	    --company-cinza-escuro: 60 7% 85%;
164	
165	    /* Tokens Momma em Modo Escuro */
166	    --momma-primary: 35 33% 45%;
167	    --momma-primary-dark: 35 33% 35%;
168	    --momma-gradient-start: 35 33% 45%;
169	    --momma-gradient-end: 133 17% 40%;
170	
171	    /* ── MIA vars dark — definição canônica em mia-chat.css. NÃO redefinir aqui. ── */
172	  }
173	}
