377	/* Animações personalizadas */
378	@keyframes fadeIn {
379	  from {
380	    opacity: 0;
381	    transform: translateY(10px);
382	  }
383	  to {
384	    opacity: 1;
385	    transform: translateY(0);
386	  }
387	}
388	
389	@keyframes slideIn {
390	  from {
391	    transform: translateX(-100%);
392	  }
393	  to {
394	    transform: translateX(0);
395	  }
396	}
397	
398	@keyframes pulse {
399	  0%, 100% {
400	    opacity: 1;
401	  }
402	  50% {
403	    opacity: 0.5;
404	  }
405	}
406	
407	@keyframes bounce {
408	  0%, 20%, 53%, 80%, 100% {
409	    transform: translate3d(0, 0, 0);
410	  }
411	  40%, 43% {
412	    transform: translate3d(0, -30px, 0);
413	  }
414	  70% {
415	    transform: translate3d(0, -15px, 0);
416	  }
417	  90% {
418	    transform: translate3d(0, -4px, 0);
419	  }
420	}
421	
422	@keyframes shimmer {
423	  0% {
424	    transform: translateX(-100%) skewX(-12deg);
425	  }
426	  100% {
427	    transform: translateX(200%) skewX(-12deg);
428	  }
429	}
430	
431	.animate-fadeIn {
432	  animation: fadeIn 0.5s ease-out;
433	}
434	
435	.animate-slideIn {
436	  animation: slideIn 0.3s ease-out;
437	}
438	
439	/* .animate-pulse e .animate-bounce removidos: deixar Tailwind aplicar
440	   o utility padrão. Isso permite que `style={{ animationDuration: 'Ns' }}`
441	   inline funcione corretamente em folhas/glows decorativos (10s, 12s, etc).
442	   Antes a regra global com shorthand `animation:` sobrescrevia o duration. */
443	
444	.animate-shimmer {
445	  animation: shimmer 2.5s infinite;
446	}
447	
448	@layer base {
449	  * {
450	    @apply border-border;
451	  }
452	
453	  body {
454	    @apply bg-background text-foreground font-sans;
455	  }
456	}
