458	/* ════════════════════════════════════════
459	   MIA Chat Animations & Utility Classes
460	   ════════════════════════════════════════ */
461	
462	/* Gradient border rotation para thinking blocks */
463	@property --thinking-angle {
464	  syntax: '<angle>';
465	  initial-value: 0deg;
466	  inherits: false;
467	}
468	
469	@keyframes mia-thinking-rotate {
470	  to { --thinking-angle: 360deg; }
471	}
472	
473	/* Text shimmer durante reasoning */
474	@keyframes mia-shimmer {
475	  0% { background-position: -200% 0; }
476	  100% { background-position: 200% 0; }
477	}
478	
479	/* Cursor blink no streaming */
480	@keyframes mia-cursor-blink {
481	  0%, 100% { opacity: 1; }
482	  50% { opacity: 0; }
483	}
484	
485	/* Float sutil para welcome avatar */
486	@keyframes mia-float {
487	  0%, 100% { transform: translateY(0); }
488	  50% { transform: translateY(-6px); }
489	}
490	
491	/* Glow pulse para avatar */
492	@keyframes mia-glow-pulse {
493	  0%, 100% { opacity: 0.15; transform: scale(1); }
494	  50% { opacity: 0.3; transform: scale(1.05); }
495	}
496	
497	/* Classes utilitárias */
498	.mia-thinking-active {
499	  position: relative;
500	  border-radius: 16px;
501	  padding: 1px;
502	  background: conic-gradient(
503	    from var(--thinking-angle),
504	    var(--mia-thinking-from),
505	    var(--mia-thinking-to),
506	    transparent 40%,
507	    var(--mia-thinking-from)
508	  );
509	  animation: mia-thinking-rotate 3s linear infinite;
510	}
511	
512	.mia-thinking-done {
513	  border-radius: 16px;
514	  padding: 1px;
515	  background: var(--mia-thinking-border);
516	}
517	
518	.mia-thinking-inner {
519	  background: var(--mia-thinking-bg);
520	  border-radius: 15px;
521	  padding: 12px 16px;
522	}
523	
524	.mia-shimmer-text {
525	  background: linear-gradient(90deg,
526	    var(--mia-text-secondary) 0%,
527	    var(--mia-accent) 50%,
528	    var(--mia-text-secondary) 100%);
529	  background-size: 200% 100%;
530	  -webkit-background-clip: text;
531	  -webkit-text-fill-color: transparent;
532	  animation: mia-shimmer 2s ease-in-out infinite;
533	}
534	
535	.mia-cursor {
536	  display: inline-block;
537	  width: 2px;
538	  height: 1.1em;
539	  background: var(--mia-accent);
540	  border-radius: 1px;
541	  margin-left: 2px;
542	  vertical-align: text-bottom;
543	  animation: mia-cursor-blink 1s ease-in-out infinite;
544	}
545	
546	/* Reduced motion */
547	@media (prefers-reduced-motion: reduce) {
548	  .mia-thinking-active { animation: none; background: var(--mia-thinking-border); }
549	  .mia-shimmer-text { animation: none; -webkit-text-fill-color: var(--mia-text-secondary); }
550	  .mia-cursor { animation: none; opacity: 1; }
551	}
552	
553	/* ============================================================================
554	   Kanban scrollbar — estilização das colunas de Encomendas
555	   ============================================================================ */
556	.kanban-scroll {
557	  scrollbar-width: thin;
558	  scrollbar-color: rgba(87, 113, 91, 0.3) transparent;
559	}
560	.kanban-scroll::-webkit-scrollbar {
561	  width: 6px;
562	}
563	.kanban-scroll::-webkit-scrollbar-track {
564	  background: transparent;
565	}
566	.kanban-scroll::-webkit-scrollbar-thumb {
567	  background: rgba(87, 113, 91, 0.25);
568	  border-radius: 3px;
569	}
570	.kanban-scroll::-webkit-scrollbar-thumb:hover {
571	  background: rgba(87, 113, 91, 0.5);
572	}
573	.dark .kanban-scroll {
574	  scrollbar-color: rgba(230, 220, 207, 0.2) transparent;
575	}
576	.dark .kanban-scroll::-webkit-scrollbar-thumb {
577	  background: rgba(230, 220, 207, 0.18);
578	}
579	.dark .kanban-scroll::-webkit-scrollbar-thumb:hover {
580	  background: rgba(230, 220, 207, 0.35);
581	}

1	import { cn } from "@/shared/lib/utils";
2	import React from "react";
3	
4	interface GlassCardProps extends React.HTMLAttributes<HTMLDivElement> {
5	    children: React.ReactNode;
6	    className?: string;
7	    gradient?: boolean;
8	}
9	
10	export const GlassCard = ({ children, className, gradient = true, variant = "default", ...props }: GlassCardProps & { variant?: "default" | "premium" }) => {
11	    const isPremium = variant === "premium";
12	
13	    return (
14	        <div
15	            className={cn(
16	                "relative overflow-hidden transition-all",
17	                // Base styles
18	                "border shadow-sm",
19	                // Default Variant
20	                !isPremium && "rounded-2xl bg-white/40 dark:bg-black/20 backdrop-blur-md border-white/20 dark:border-white/10 hover:shadow-md",
21	                // Premium Variant (Apple-style widget)
22	                isPremium && [
23	                    "rounded-[2rem]",
24	                    "bg-white/60 dark:bg-black/20",
25	                    "backdrop-blur-xl saturate-150",
26	                    "border-white/50 dark:border-white/10",
27	                    "shadow-[0_8px_32px_rgba(0,0,0,0.12)]",
28	                    "hover:shadow-[0_16px_48px_rgba(197,160,101,0.2)]"
29	                ],
30	                className
31	            )}
32	            {...props}
33	        >
34	            {gradient && (
35	                <div className={cn(
36	                    "absolute inset-0 pointer-events-none",
37	                    isPremium
38	                        ? "bg-gradient-to-br from-white/40 via-transparent to-[#C5A065]/5"
39	                        : "bg-gradient-to-br from-white/20 via-transparent to-transparent"
